"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def UPDATE_INVENTORY(purchases, deliveries):
    inventory = []
    for item in purchases:
        if (item in inventory):
            inventory[item] = (inventory[item] - purchases[item])
        else:
            inventory[item] = (-purchases[item])
    for item in deliveries:
        if (item in inventory):
            inventory[item] = (inventory[item] + deliveries[item])
        else:
            inventory[item] = deliveries[item]
    return inventory

print(UPDATE_INVENTORY({"item1": 10, "item2": 20}, {"item1": 5, "item3": 15}))